nextflow_process {

    name "Test Process HAPIBD"
    script "../main.nf"
    process "HAPIBD"

    tag "modules"
    tag "modules_nfcore"
    tag "hapibd"

    test("homo sapiens - VCF, map, exclude sample") {

        when {
            process {
                """
                excludeSample = channel.of('NA12879').collectFile(name:"excludeSample.txt", newLine:true)
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz', checkIfExists: true)
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.plink.map', checkIfExists: true)
                input[2] = excludeSample
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert file(process.out.log[0][1]).text.contains('End Time') },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["hbd", "ibd", "log"])).match()}
            )
        }
    }

    test("homo sapiens - VCF -- stub") {
        options '-stub'

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz', checkIfExists: true)
                ]
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

}

